import { AppError } from "./errorHandler.js";

export function validateProductId(productId) {
  if (!productId || typeof productId !== "string" || productId.trim() === "") {
    throw new AppError(400, "Invalid product ID");
  }
  return productId.trim();
}

export function validateUserId(userId) {
  if (!userId || typeof userId !== "string" || userId.trim() === "") {
    throw new AppError(400, "Invalid user ID");
  }
  return userId.trim();
}

export function validateWishlistBody(body) {
  if (!body || !body.productId) {
    throw new AppError(400, "Missing productId in request body");
  }
  return { productId: validateProductId(body.productId) };
}

export function validateTryOnBody(body) {
  if (!body || !body.userId || !body.accessoryId) {
    throw new AppError(400, "Missing userId or accessoryId");
  }

  const data = {
    userId: validateUserId(body.userId),
    userEmail: body.userEmail ? body.userEmail.toString().trim() : null,
    productId: body.productId ? body.productId.toString().trim() : null,
    accessoryId: body.accessoryId?.toString().trim(),
    faceRatio: body.faceRatio !== null && body.faceRatio !== undefined ? Number(body.faceRatio) : null,
    earlobeDistance:
      body.earlobeDistance !== null && body.earlobeDistance !== undefined
        ? Number(body.earlobeDistance)
        : null,
    earlobeLength:
      body.earlobeLength !== null && body.earlobeLength !== undefined
        ? Number(body.earlobeLength)
        : null,
    fps: body.fps !== null && body.fps !== undefined ? Number(body.fps) : null,
    sessionId: body.sessionId ? body.sessionId.toString().trim() : null,
    trackingStatus: body.trackingStatus ? body.trackingStatus.toString().trim() : null
  };

  if (!data.accessoryId) {
    throw new AppError(400, "Invalid accessoryId");
  }

  if (data.faceRatio !== null && !Number.isFinite(data.faceRatio)) {
    throw new AppError(400, "Invalid faceRatio");
  }

  if (data.earlobeDistance !== null && !Number.isFinite(data.earlobeDistance)) {
    throw new AppError(400, "Invalid earlobeDistance");
  }

  if (data.earlobeLength !== null && !Number.isFinite(data.earlobeLength)) {
    throw new AppError(400, "Invalid earlobeLength");
  }

  if (data.fps !== null && !Number.isFinite(data.fps)) {
    throw new AppError(400, "Invalid fps");
  }

  return data;
}

export function validateSusResponseBody(body) {
  if (!body || !body.userId || !Array.isArray(body.answers)) {
    throw new AppError(400, "Missing userId or answers array");
  }

  if (body.answers.length !== 10) {
    throw new AppError(400, "answers array must contain exactly 10 items");
  }

  const answers = body.answers.map((answer) => {
    const num = Number(answer);
    if (!Number.isFinite(num) || num < 1 || num > 5) {
      throw new AppError(400, "Each answer must be a number between 1 and 5");
    }
    return num;
  });

  return {
    userId: validateUserId(body.userId),
    answers
  };
}
